Table.CommandText:
SELECT
    TOP 1 PQT10.LineText
FROM PQT1
INNER JOIN PQT10 ON PQT1.[DocEntry] = PQT10.[DocEntry] AND PQT10.AftLineNum = {?lineNum@}
WHERE PQT1.[DocEntry] = {?DocKey@}

